import{_ as a,o,c as i,a0 as s}from"./chunks/framework.BdMypFZ5.js";const u=JSON.parse('{"title":"Database Schema","description":"","frontmatter":{},"headers":[],"relativePath":"database/schema.md","filePath":"database/schema.md"}'),l={name:"database/schema.md"};function r(t,e,c,d,n,p){return o(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="database-schema" tabindex="-1">Database Schema <a class="header-anchor" href="#database-schema" aria-label="Permalink to &quot;Database Schema&quot;">​</a></h1><p>The database for the URLC System is built using <strong>PostgreSQL</strong> hosted on <strong>Supabase</strong>. The schema is managed dynamically via Laravel Migrations.</p><h2 id="core-entities" tabindex="-1">Core Entities <a class="header-anchor" href="#core-entities" aria-label="Permalink to &quot;Core Entities&quot;">​</a></h2><h3 id="_1-users" tabindex="-1">1. <code>users</code> <a class="header-anchor" href="#_1-users" aria-label="Permalink to &quot;1. `users`&quot;">​</a></h3><p>Stores user authentication information, roles, and registration metadata.</p><ul><li><code>id</code> (bigint, PK)</li><li><code>name</code> (varchar)</li><li><code>email</code> (varchar, Unique)</li><li><code>role</code> (varchar) — <code>researcher</code>, <code>reviewer</code>, <code>coordinator</code>, <code>staff</code>, <code>admin</code>, <code>recording_staff</code></li><li><code>department</code> (varchar, Nullable)</li><li><code>is_approved</code> (boolean) — Admin accounts require manual activation.</li><li><code>timestamps</code></li></ul><h3 id="_2-research-proposals" tabindex="-1">2. <code>research_proposals</code> <a class="header-anchor" href="#_2-research-proposals" aria-label="Permalink to &quot;2. `research_proposals`&quot;">​</a></h3><p>Stores details of research proposals submitted by researchers.</p><ul><li><code>id</code> (bigint, PK)</li><li><code>proposal_code</code> (varchar, Unique)</li><li><code>user_id</code> (bigint, FK) — Owner/lead researcher of the proposal.</li><li><code>title</code> (varchar)</li><li><code>abstract</code> (text)</li><li><code>status</code> (varchar) — <code>draft</code>, <code>submitted</code>, <code>under_review</code>, <code>approved</code>, <code>rejected</code></li><li><code>phase</code> (integer) — Tracked development stage.</li><li><code>reviewer_id</code> (bigint, FK, Nullable) — Assigned reviewer.</li><li><code>timestamps</code></li></ul><h3 id="_3-proposal-collaborators" tabindex="-1">3. <code>proposal_collaborators</code> <a class="header-anchor" href="#_3-proposal-collaborators" aria-label="Permalink to &quot;3. `proposal_collaborators`&quot;">​</a></h3><p>Maintains relations for secondary researchers working on a proposal.</p><ul><li><code>id</code> (bigint, PK)</li><li><code>proposal_id</code> (bigint, FK)</li><li><code>user_id</code> (bigint, FK)</li><li><code>timestamps</code></li></ul><h3 id="_4-proposal-documents" tabindex="-1">4. <code>proposal_documents</code> <a class="header-anchor" href="#_4-proposal-documents" aria-label="Permalink to &quot;4. `proposal_documents`&quot;">​</a></h3><p>Tracks file uploads associated with a proposal (stored privately in Supabase Storage).</p><ul><li><code>id</code> (bigint, PK)</li><li><code>proposal_id</code> (bigint, FK)</li><li><code>file_path</code> (varchar) — File path inside the S3 storage bucket.</li><li><code>file_name</code> (varchar)</li><li><code>file_type</code> (varchar)</li><li><code>timestamps</code></li></ul><h3 id="_5-activity-log" tabindex="-1">5. <code>activity_log</code> <a class="header-anchor" href="#_5-activity-log" aria-label="Permalink to &quot;5. `activity_log`&quot;">​</a></h3><p>Audit trails for all critical database modifications and user sessions.</p><ul><li><code>id</code> (bigint, PK)</li><li><code>log_name</code> (varchar, Nullable)</li><li><code>description</code> (text)</li><li><code>subject_type</code> / <code>subject_id</code> (polymorphic morphs)</li><li><code>causer_type</code> / <code>causer_id</code> (polymorphic morphs)</li><li><code>properties</code> (json, Nullable)</li><li><code>event</code> (varchar)</li><li><code>batch_uuid</code> (uuid, Nullable)</li><li><code>timestamps</code></li></ul><hr><h2 id="schema-diagram-relationships" tabindex="-1">Schema Diagram (Relationships) <a class="header-anchor" href="#schema-diagram-relationships" aria-label="Permalink to &quot;Schema Diagram (Relationships)&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">erDiagram</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    users ||--o{ research_proposals : &quot;owns&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    users ||--o{ proposal_collaborators : &quot;collaborates on&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    users ||--o{ research_proposals : &quot;reviews&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    </span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    research_proposals ||--o{ proposal_documents : &quot;contains&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    research_proposals ||--o{ proposal_collaborators : &quot;includes&quot;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    </span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    users ||--o{ activity_log : &quot;causes&quot;</span></span></code></pre></div>',21)])])}const m=a(l,[["render",r]]);export{u as __pageData,m as default};
